//! The ThingWorx 10.2 widget catalogue: what a widget is called, the properties Composer gives it
//! when it is dropped on a mashup, and, for the PTCS widgets, which properties bind which way and
//! which events and services it has.
//!
//! The catalogue is for ThingWorx 10.2 only. `widgets/catalog.json` is generated by hand from a 10.2
//! installation by `scripts/generate_widget_catalog.mjs` (which records the SHA-256 of what it read),
//! plus the curated `scripts/widget_catalog_overlay.json`; it is never edited by hand. A widget
//! without a contract can be placed but not bound. Properties a widget makes up from
//! its own configuration (a KPI's thresholds, a collection's mashup parameters) are not in it.

use crate::core::codes::{Coded, ErrorCode};
use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use std::cell::RefCell;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::LazyLock;

const CATALOG: &str = include_str!("widgets/catalog.json");

/// The platform the catalogue describes.
pub(crate) const PLATFORM: &str = "10.2";

#[derive(Debug, Deserialize)]
pub struct Catalog {
    #[allow(
        dead_code,
        reason = "deserialised from the embedded catalogue; checked only by tests"
    )]
    pub(crate) platform: String,
    /// Properties every widget has, whatever its contract says.
    pub(crate) base_properties: BTreeMap<String, PropertyContract>,
    /// What Composer writes on a dropped widget after its defaults.
    pub(crate) dropped: Dropped,
    /// Every widget type the platform ships, including those without a contract here.
    pub(crate) platform_types: BTreeSet<String>,
    pub(crate) widgets: Vec<Widget>,
}

#[derive(Debug, Deserialize)]
pub(crate) struct Dropped {
    /// On every PTCS widget.
    pub(crate) ptcs: Map<String, Value>,
    pub(crate) flexcontainer: Map<String, Value>,
}

#[derive(Clone, Debug, Deserialize)]
pub struct Widget {
    /// The `Type` a mashup writes, e.g. `ptcsbutton`.
    #[serde(rename = "type")]
    pub(crate) type_id: String,
    pub(crate) aliases: Vec<String>,
    /// Composer's label, written as `__TypeDisplayName`.
    pub type_display_name: String,
    /// The `DisplayName` stem: a dropped widget is `<display_name>-<n>`, or just this when it is
    /// not `numbered`.
    pub(crate) display_name: String,
    pub(crate) numbered: bool,
    /// Whether other widgets go inside it.
    pub(crate) container: bool,
    /// Whether it can fill the container it is alone in (Composer's `supportsAutoResize`).
    #[serde(default)]
    pub(crate) auto_resize: bool,
    /// Composer's defaults, in Composer's order.
    pub(crate) defaults: Map<String, Value>,
    /// The binding contract; absent for a widget whose contract the catalogue does not know.
    pub(crate) properties: Option<BTreeMap<String, PropertyContract>>,
    pub(crate) events: Option<Vec<String>>,
    pub(crate) services: Option<Vec<String>>,
    /// A function widget (expression, validator, navigation, ...): it sits under the mashup root,
    /// beside the layout, and draws nothing.
    #[serde(default)]
    pub function: bool,
    /// A legacy widget that stays readable in existing mashups; adding one adds this instead.
    #[serde(default)]
    pub(crate) replaced_by: Option<String>,
    /// An older Composer layout widget (the shape), not a PTCS one: Composer gives it none of
    /// the properties it adds to a dropped PTCS widget.
    #[serde(default)]
    pub(crate) legacy: bool,
    /// Defined by one of the solution's extension projects, not shipped with the platform.
    #[serde(skip)]
    pub(crate) extension: bool,
    /// Where a widget outside the embedded catalogue came from (the widget cache), for notes.
    #[serde(skip)]
    pub(crate) provenance: Option<String>,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub(crate) struct PropertyContract {
    pub(crate) base_type: Option<String>,
    /// Runtime accepts CSS size text as well as Composer's numeric base type.
    #[serde(default, skip_serializing_if = "is_false")]
    pub(crate) css_size: bool,
    /// Can be bound from: the widget sets it.
    #[serde(default, skip_serializing_if = "is_false")]
    pub(crate) source: bool,
    /// Can be bound to: something else sets it.
    #[serde(default, skip_serializing_if = "is_false")]
    pub(crate) target: bool,
    #[serde(default = "yes", skip_serializing_if = "is_true")]
    pub(crate) editable: bool,
    /// The values a select property allows, when it lists them.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub(crate) options: Vec<Value>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub(crate) values: Vec<PropertyValue>,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq, Eq)]
pub struct PropertyValue {
    pub value: Value,
    pub label: String,
}

impl PropertyContract {
    pub(crate) fn allowed_values(&self) -> impl Iterator<Item = &Value> {
        self.values
            .iter()
            .map(|entry| &entry.value)
            .chain(&self.options)
    }
}

const fn yes() -> bool {
    true
}

const fn is_false(value: &bool) -> bool {
    !*value
}

const fn is_true(value: &bool) -> bool {
    *value
}

/// Widgets beyond the embedded catalogue: the legacy and extension widgets of the widget cache
/// (`twaco widgets --platform`), consulted after the embedded entries. It is read when a solution
/// is loaded, per thread, so a thread that has loaded none sees the embedded catalogue alone.
#[derive(Debug, Default)]
pub(crate) struct Ambient {
    pub(crate) widgets: Vec<Widget>,
}

thread_local! {
    static AMBIENT: RefCell<Option<&'static Ambient>> = const { RefCell::new(None) };
}

/// Make `ambient` (or nothing) the cache this thread's lookups consult after the embedded entries.
pub(crate) fn set_ambient(ambient: Option<&'static Ambient>) {
    AMBIENT.with(|slot| *slot.borrow_mut() = ambient);
}

fn ambient() -> Option<&'static Ambient> {
    AMBIENT.with(|slot| *slot.borrow())
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum CatalogError {
    #[error("no widget is called `{word}` in the ThingWorx {PLATFORM} catalogue{}{}", hint(.close), absent(.word))]
    Unknown { word: String, close: Vec<String> },
    /// A widget type id the platform ships whose contract the catalogue lacks. It never resolves to
    /// a modern widget: the two have different events and properties.
    #[error("unknown (legacy widget `{word}`; not in the catalogue): twaco has no contract for it and cannot author it; one already on a page is carried as-is{}{}", modern(.close), absent(.word))]
    Legacy { word: String, close: Vec<String> },
}

fn modern(close: &[String]) -> String {
    if close.is_empty() {
        String::new()
    } else {
        format!(
            ". Its modern counterparts have other events and properties: {}",
            close.join(", ")
        )
    }
}

/// What the catalogue lacks on purpose (Gauge, Web Frame): the closest widget it has.
fn absent(word: &str) -> String {
    super::widgets_view::absent_note(word)
        .map(|note| format!(". {note}"))
        .unwrap_or_default()
}

fn hint(close: &[String]) -> String {
    if close.is_empty() {
        "; `twaco widgets` lists them".to_string()
    } else {
        format!("; did you mean {}?", close.join(", "))
    }
}

impl Coded for CatalogError {
    fn code(&self) -> ErrorCode {
        ErrorCode::InvalidArguments
    }
}

static PARSED: LazyLock<Catalog> = LazyLock::new(|| {
    serde_json::from_str(CATALOG).expect("the embedded widget catalogue is valid; a test checks it")
});

/// The embedded catalogue.
pub fn catalog() -> &'static Catalog {
    &PARSED
}

pub(crate) static MIGRATIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("widgets/migrations.json"))
        .expect("widgets/migrations.json is valid JSON")
});

/// The name Composer renames the legacy property `name` of a `type_id` widget to when it opens
/// the mashup (`CollapseByDefault` becomes `Collapsed`), read from its migrators.
pub(crate) fn migrated_property(type_id: &str, name: &str) -> Option<&'static str> {
    MIGRATIONS["renames"][type_id][name].as_str()
}

/// Whether the old and new names hold different kinds of value (a legacy `TargetWindow` is `new`,
/// `replace` or `popup`; `TargetWindowType` is another list), so the value cannot move across.
pub(crate) fn migration_changes_values(type_id: &str, name: &str) -> bool {
    MIGRATIONS["values_differ"][type_id]
        .as_array()
        .is_some_and(|names| names.iter().any(|n| n == name))
}

/// Rename the legacy property names Composer migrates, in a mashup's content, as Composer does
/// on open: a widget property whose new name is not set, and the bindings that name it. A legacy
/// name whose new name is already set, or whose values differ, stays as it is (its value is never
/// dropped). One note per rename.
pub(crate) fn migrate_content(content: &mut Value) -> Vec<String> {
    fn walk(
        widget: &mut Value,
        renamed: &mut BTreeMap<(String, String), String>,
        notes: &mut Vec<String>,
    ) {
        let type_id = widget["Properties"]["Type"]
            .as_str()
            .unwrap_or_default()
            .to_string();
        let id = widget["Properties"]["Id"]
            .as_str()
            .unwrap_or_default()
            .to_string();
        if let Some(props) = widget["Properties"].as_object_mut() {
            let olds: Vec<String> = props
                .keys()
                .filter(|name| migrated_property(&type_id, name).is_some())
                .cloned()
                .collect();
            for old in olds {
                let new = migrated_property(&type_id, &old).expect("listed above");
                if props.contains_key(new) || migration_changes_values(&type_id, &old) {
                    continue;
                }
                if let Some(value) = props.remove(&old) {
                    props.insert(new.to_string(), value);
                    renamed.insert((id.clone(), old.clone()), new.to_string());
                    notes.push(format!("{id}: renamed property {old} to {new}, as Composer does when it opens the mashup"));
                }
            }
        }
        for child in widget["Widgets"].as_array_mut().into_iter().flatten() {
            walk(child, renamed, notes);
        }
    }
    let mut renamed = BTreeMap::new();
    let mut notes = Vec::new();
    walk(&mut content["UI"], &mut renamed, &mut notes);
    if !renamed.is_empty() {
        for binding in content["DataBindings"].as_array_mut().into_iter().flatten() {
            let ends = [
                ("SourceArea", "SourceId", "SourceProperty"),
                ("TargetArea", "TargetId", "TargetProperty"),
            ];
            for (area, id, key) in ends {
                if binding[area] != "UI" {
                    continue;
                }
                let widget = binding[id].as_str().unwrap_or_default().to_string();
                for map in binding["PropertyMaps"].as_array_mut().into_iter().flatten() {
                    let old = map[key].as_str().unwrap_or_default().to_string();
                    if let Some(new) = renamed.get(&(widget.clone(), old)) {
                        map[key] = Value::String(new.clone());
                    }
                }
            }
        }
    }
    notes
}

/// Configuration-created properties use the same contract in commands, specs and validation.
pub(crate) fn dynamic_property(
    type_id: &str,
    props: &Value,
    name: &str,
    data_bound: bool,
) -> Option<PropertyContract> {
    // Composer exposes 100 sources when the series count is automatic (unset).
    let chart_source = catalog().by_type(type_id).is_some_and(|w| {
        type_id.starts_with("ptcschart") && w.defaults.contains_key("MultipleDataSources")
    }) && props["MultipleDataSources"] == true
        && name.strip_prefix("DataSource").is_some_and(|suffix| {
            let count = props["NumberOfSeries"]
                .as_u64()
                .or_else(|| props["NumberOfSeries"].as_str()?.parse().ok())
                .unwrap_or(if props["NumberOfSeries"].is_null() {
                    100
                } else {
                    0
                });
            suffix
                .parse::<u64>()
                .ok()
                .is_some_and(|n| n.to_string() == suffix && (1..=count.min(100)).contains(&n))
        });
    let base = if chart_source {
        "INFOTABLE".into()
    } else if type_id == "ptcscollection" {
        // Composer gives a collection one `Event:<field>` source per field of its Data table (the
        // value of that field in the last cell event), whatever the cell mashup is.
        if name
            .strip_prefix("Event:")
            .is_some_and(|field| !field.is_empty())
        {
            return Some(PropertyContract {
                base_type: None,
                css_size: false,
                source: true,
                target: false,
                editable: false,
                options: Vec::new(),
                values: Vec::new(),
            });
        }
        let globals = json_object(&props["MashupGlobalPropertyBinding"])?;
        globals.get(name)?.as_str()?.to_string()
    } else if type_id == "ptcsmenubutton" {
        let item = name
            .strip_suffix("_Visible")
            .or_else(|| name.strip_suffix("_Disabled"))?;
        if !menu_item(props, item, data_bound) {
            return None;
        }
        "BOOLEAN".into()
    } else {
        return None;
    };
    Some(PropertyContract {
        base_type: Some(base),
        css_size: false,
        source: type_id == "ptcscollection",
        target: true,
        editable: !chart_source,
        options: vec![],
        values: vec![],
    })
}

fn json_object(value: &Value) -> Option<Value> {
    let value = match value {
        Value::String(text) => serde_json::from_str(text).ok()?,
        other => other.clone(),
    };
    value.is_object().then_some(value)
}

fn menu_item(props: &Value, item: &str, data_bound: bool) -> bool {
    if props["ItemConfigurationMode"] != "widgetProperties" || item.is_empty() {
        return false;
    }
    data_bound
        || props["Data"]["rows"]
            .as_array()
            .into_iter()
            .flatten()
            .any(|row| row["menuId"] == item)
}

pub(crate) fn dynamic_event(type_id: &str, props: &Value, event: &str, data_bound: bool) -> bool {
    type_id == "ptcsmenubutton"
        && event
            .strip_suffix("_Clicked")
            .is_some_and(|item| menu_item(props, item, data_bound))
}

pub(crate) fn property_bound(content: &Value, id: &str, property: &str) -> bool {
    content["DataBindings"]
        .as_array()
        .into_iter()
        .flatten()
        .any(|binding| {
            binding["TargetArea"] == "UI"
                && binding["TargetId"] == id
                && binding["PropertyMaps"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .any(|map| map["TargetProperty"] == property)
        })
}

pub(crate) fn configuration_warnings(content: &Value) -> Vec<String> {
    fn walk(widget: &Value, content: &Value, out: &mut Vec<String>) {
        let props = &widget["Properties"];
        let id = props["Id"].as_str().unwrap_or_default();
        if props["Type"].as_str().is_some_and(|kind| {
            !matches!(kind, "mashup" | "targetmashup") && catalog().by_type(kind).is_none()
        }) {
            out.push(format!("{id}: widget contract is not in the embedded catalogue; events and bindings cannot be checked and are carried as-is"));
        }
        if props["Type"] == "ptcsmenubutton"
            && props["ItemConfigurationMode"] == "widgetProperties"
            && property_bound(content, id, "Data")
        {
            out.push(format!("{id}: menu Data is bound; per-item ids cannot be checked offline; wiring is carried as-is"));
        }
        for child in widget["Widgets"].as_array().into_iter().flatten() {
            walk(child, content, out);
        }
    }
    let mut out = vec![];
    walk(&content["UI"], content, &mut out);
    out
}

impl Catalog {
    /// The widget with this exact `Type`: an embedded entry, else one of the widget cache.
    pub fn by_type(&self, type_id: &str) -> Option<&Widget> {
        self.widgets
            .iter()
            .find(|widget| widget.type_id == type_id)
            .or_else(|| {
                ambient()?
                    .widgets
                    .iter()
                    .find(|widget| widget.type_id == type_id)
            })
    }

    /// The embedded widgets, then those of the widget cache.
    pub(crate) fn all(&self) -> impl Iterator<Item = &Widget> {
        self.widgets
            .iter()
            .chain(ambient().into_iter().flat_map(|a| a.widgets.iter()))
    }

    /// The widget a person names: its type or an alias, ignoring case. An embedded entry wins; the
    /// widget cache adds the legacy and extension widgets the catalogue lacks.
    pub(crate) fn resolve(&self, word: &str) -> Result<&Widget, CatalogError> {
        self.resolve_embedded(word).or_else(|error| {
            let wanted = word.trim();
            ambient()
                .and_then(|a| {
                    a.widgets
                        .iter()
                        .find(|widget| widget.names().any(|name| name.eq_ignore_ascii_case(wanted)))
                })
                .ok_or(error)
        })
    }

    /// [`Catalog::resolve`] over the embedded entries alone.
    fn resolve_embedded(&self, word: &str) -> Result<&Widget, CatalogError> {
        let wanted = word.trim().to_ascii_lowercase();
        self.widgets
            .iter()
            .find(|widget| {
                widget
                    .names()
                    .any(|name| name.eq_ignore_ascii_case(&wanted))
            })
            // A legacy widget's word adds its replacement (`expression` adds `expression2`).
            .map(|widget| {
                widget
                    .replaced_by
                    .as_deref()
                    .and_then(|replacement| self.by_type(replacement))
                    .unwrap_or(widget)
            })
            .ok_or_else(|| {
                let close = self
                    .search(&wanted)
                    .into_iter()
                    .take(5)
                    .map(|widget| widget.type_id.clone())
                    .collect();
                if self.platform_types.contains(&wanted) {
                    CatalogError::Legacy {
                        word: wanted.clone(),
                        close,
                    }
                } else {
                    CatalogError::Unknown {
                        word: word.to_string(),
                        close,
                    }
                }
            })
    }

    /// The widget `mashup add` places for a word. Everyday words that are also legacy type ids
    /// (`button`, `label`, `container`) add the modern widget, because twaco only ever authors
    /// modern ones; they are accepted here and nowhere else, so describing or reading a page never
    /// takes a legacy type for a modern one.
    pub(crate) fn resolve_for_add(&self, word: &str) -> Result<&Widget, CatalogError> {
        const EVERYDAY: &[(&str, &str)] = &[
            ("button", "ptcsbutton"),
            ("checkbox", "ptcscheckbox"),
            ("container", "flexcontainer"),
            ("panel", "flexcontainer"),
            ("divider", "ptcsdivider"),
            ("image", "ptcsimage"),
            ("label", "ptcslabel"),
            ("link", "ptcslink"),
            ("slider", "ptcsslider"),
            ("tabs", "ptcstabset"),
            ("textarea", "ptcstextarea"),
            ("tree", "ptcstreeselector"),
            ("collection", "ptcscollection"),
            ("navigation", "navigationfunction"),
            ("autorefresh", "autorefreshfunction"),
        ];
        let wanted = word.trim().to_ascii_lowercase();
        self.resolve_embedded(word).or_else(|error| {
            EVERYDAY
                .iter()
                .find(|(name, _)| *name == wanted)
                .and_then(|(_, type_id)| self.by_type(type_id))
                .ok_or(error)
        })
    }

    /// Widgets whose type, alias or label contains `text`, ignoring case; all of them for "".
    pub(crate) fn search(&self, text: &str) -> Vec<&Widget> {
        let wanted = text.trim().to_ascii_lowercase();
        self.all()
            .filter(|widget| {
                widget
                    .names()
                    .chain(std::iter::once(widget.type_display_name.as_str()))
                    .any(|name| name.to_ascii_lowercase().contains(&wanted))
            })
            .collect()
    }
}

impl Widget {
    /// These widgets expose the native reset service although their builders omit it from the
    /// design-time service list (Composer-authored mashups wire events to it). Keep command
    /// authoring and derived event wiring in agreement.
    pub(crate) fn has_service(&self, name: &str) -> bool {
        // The runtime/shared widget definitions opt these into the default reset service.
        const RESETTABLE: &[&str] = &[
            "ptcstogglebutton",
            "ptcsdatepicker",
            "ptcstextfield",
            "ptcstextarea",
            "ptcsdropdown",
            "ptcscheckbox",
            "ptcslist",
            "ptcsrte",
            "ptcskpidial",
            "ptcsdynamicpanel",
            "ptcsfileupload",
            "ptcstoolbar",
            "ptcschartline",
            "ptcschartbar",
            "ptcschartcombo",
            "ptcschartpie",
            "ptcschartwaterfall",
            "ptcschartschedule",
            "ptcschartpareto",
        ];
        self.services
            .as_ref()
            .is_some_and(|services| services.iter().any(|s| s == name))
            || (name == "ResetToDefaultValue" && RESETTABLE.contains(&self.type_id.as_str()))
    }
    /// A widget an extension project defines: numbered as Composer numbers every widget it has no
    /// entry for (`<type>-<n>`), never a container, never a function.
    pub(crate) fn extension(
        type_id: String,
        label: String,
        auto_resize: bool,
        defaults: Map<String, Value>,
        properties: BTreeMap<String, PropertyContract>,
        events: Vec<String>,
        services: Option<Vec<String>>,
    ) -> Widget {
        Widget {
            display_name: type_id.clone(),
            type_id,
            aliases: Vec::new(),
            type_display_name: label,
            numbered: true,
            container: false,
            auto_resize,
            defaults,
            properties: Some(properties),
            events: Some(events),
            services,
            function: false,
            replaced_by: None,
            legacy: false,
            extension: true,
            provenance: None,
        }
    }

    /// Its type and aliases.
    pub(crate) fn names(&self) -> impl Iterator<Item = &str> {
        std::iter::once(self.type_id.as_str()).chain(self.aliases.iter().map(String::as_str))
    }

    /// Whether the catalogue knows what its properties and events are.
    pub(crate) fn has_contract(&self) -> bool {
        self.properties.is_some()
    }

    /// A property's contract, the widget's own or one every widget has. `None` when the widget has
    /// no contract or no such property.
    pub(crate) fn property(&self, name: &str) -> Option<&PropertyContract> {
        let own = self.properties.as_ref()?;
        own.get(name)
            .or_else(|| catalog().base_properties.get(name))
    }

    /// The refusal for a property `subject` (a widget id or type) does not have, naming close
    /// real ones or where to list them.
    pub(crate) fn no_property(&self, subject: &str, name: &str) -> String {
        if let Some(new) = migrated_property(&self.type_id, name) {
            return format!(
                "{subject} has no property {name}; Composer renames it to {new} when it opens a mashup, so use {new}"
            );
        }
        let close = self.close_properties(name);
        if close.is_empty() {
            format!(
                "{subject} has no property {name}; `twaco widgets {}` lists them",
                self.type_id
            )
        } else {
            format!(
                "{subject} has no property {name}; did you mean {}?",
                close.join(", ")
            )
        }
    }

    /// Real property names close to `name`, for a refusal: by spelling, and by the words other
    /// tools use for the same thing (a placeholder is ThingWorx's hint text).
    pub(crate) fn close_properties(&self, name: &str) -> Vec<String> {
        const SYNONYMS: &[(&str, &str)] = &[
            ("placeholder", "hinttext"),
            ("caption", "label"),
            ("title", "label"),
            ("enabled", "disabled"),
            ("hidden", "visible"),
            ("tooltip", "tooltipfield"),
        ];
        let wanted = name.to_ascii_lowercase();
        let mut names: Vec<&String> = self.defaults.keys().collect();
        if let Some(own) = &self.properties {
            names.extend(own.keys());
        }
        names.sort();
        names.dedup();
        let mut close: Vec<(usize, &String)> = names
            .into_iter()
            .filter_map(|candidate| {
                let lower = candidate.to_ascii_lowercase();
                let synonym = SYNONYMS
                    .iter()
                    .any(|(word, real)| wanted.contains(word) && lower.contains(real));
                let distance = strsim::levenshtein(&wanted, &lower);
                (synonym || distance <= 2 || (wanted.len() > 4 && lower.contains(&wanted)))
                    .then_some((if synonym { 0 } else { distance }, candidate))
            })
            .collect();
        close.sort();
        close
            .into_iter()
            .take(3)
            .map(|(_, name)| name.clone())
            .collect()
    }

    /// The empty value of a numbered property Composer adds only once it is used, so the
    /// catalogue has no default for it: a chart's `DataField<N>` (series N's field) and
    /// `YAxis<N>MinimumValue`/`MaximumValue` (fixed axis bounds). The catalogue's own
    /// `DataLabel<N>` or `YAxis<N>Label` proves the index exists.
    pub(crate) fn numbered_default(&self, name: &str) -> Option<Value> {
        // A tab set's per-tab properties, Tab<n><Suffix>; set checks n against NumberOfTabs.
        if self.type_id == "ptcstabset" {
            if let Some(rest) = name.strip_prefix("Tab") {
                let digits = rest.bytes().take_while(u8::is_ascii_digit).count();
                if digits > 0 {
                    match &rest[digits..] {
                        "Name" | "Value" | "Icon" | "SVGIcon" => {
                            return Some(Value::String(String::new()))
                        }
                        "Visible" => return Some(Value::Bool(true)),
                        "Disabled" => return Some(Value::Bool(false)),
                        _ => {}
                    }
                }
            }
        }
        const FAMILIES: &[(&str, &str, &str, &str)] = &[
            ("DataField", "", "DataLabel", ""),
            ("YAxis", "MinimumValue", "YAxis", "Label"),
            ("YAxis", "MaximumValue", "YAxis", "Label"),
        ];
        FAMILIES
            .iter()
            .find_map(|(prefix, suffix, witness, witness_suffix)| {
                let number = name.strip_prefix(prefix)?.strip_suffix(suffix)?;
                (!number.is_empty()
                    && number.bytes().all(|b| b.is_ascii_digit())
                    && self
                        .defaults
                        .contains_key(&format!("{witness}{number}{witness_suffix}")))
                .then(|| {
                    if suffix.is_empty() {
                        Value::String(String::new())
                    } else {
                        Value::from(0)
                    }
                })
            })
    }

    /// ` did you mean ...?` for an event or service name the widget lacks, or nothing when no
    /// real name is close.
    pub(crate) fn did_you_mean(names: Option<&Vec<String>>, wanted: &str) -> String {
        let wanted = wanted.to_ascii_lowercase();
        let mut close: Vec<(usize, &String)> = names
            .into_iter()
            .flatten()
            .filter_map(|name| {
                let lower = name.to_ascii_lowercase();
                let distance = strsim::levenshtein(&wanted, &lower);
                (distance <= 2 || (wanted.len() > 3 && lower.contains(&wanted)))
                    .then_some((distance, name))
            })
            .collect();
        close.sort();
        if close.is_empty() {
            String::new()
        } else {
            format!(
                "; did you mean {}?",
                close
                    .into_iter()
                    .take(3)
                    .map(|(_, name)| name.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            )
        }
    }

    pub(crate) fn has_event(&self, name: &str) -> bool {
        self.events
            .as_ref()
            .is_some_and(|events| events.iter().any(|event| event == name))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    #[test]
    fn native_reset_services_follow_the_runtime_widget_flags() {
        for kind in [
            "ptcscheckbox",
            "ptcsdatepicker",
            "ptcsdropdown",
            "ptcstextfield",
            "ptcstextarea",
            "ptcstogglebutton",
            "ptcsdynamicpanel",
            "ptcsfileupload",
            "ptcskpidial",
            "ptcslist",
            "ptcsrte",
            "ptcstoolbar",
            "ptcschartline",
            "ptcschartbar",
            "ptcschartcombo",
            "ptcschartpie",
            "ptcschartwaterfall",
            "ptcschartschedule",
            "ptcschartpareto",
        ] {
            assert!(
                catalog()
                    .by_type(kind)
                    .unwrap()
                    .has_service("ResetToDefaultValue"),
                "{kind}"
            );
        }
        assert!(!catalog()
            .by_type("ptcsbutton")
            .unwrap()
            .has_service("ResetToDefaultValue"));
    }

    #[test]
    fn a_misnamed_property_suggests_the_real_one() {
        let field = catalog().by_type("ptcstextfield").unwrap();
        assert_eq!(field.close_properties("PlaceholderText")[0], "HintText");
        assert!(field
            .close_properties("Lable")
            .contains(&"Label".to_string()));
        assert!(field.close_properties("Zzzzzz").is_empty());
        assert_eq!(
            catalog().resolve("datepicker").unwrap().type_id,
            "ptcsdatepicker"
        );
    }

    #[test]
    fn the_embedded_catalogue_is_for_10_2_and_every_widget_has_composer_defaults() {
        let catalog = catalog();
        assert_eq!(catalog.platform, PLATFORM);
        assert!(catalog.widgets.len() >= 40, "{}", catalog.widgets.len());
        for widget in &catalog.widgets {
            assert!(!widget.defaults.is_empty(), "{}", widget.type_id);
            assert!(!widget.type_display_name.is_empty(), "{}", widget.type_id);
            assert!(!widget.display_name.is_empty(), "{}", widget.type_id);
        }
        let source: Value = serde_json::from_str(CATALOG).unwrap();
        for input in ["widget_meta_values", "widget_contracts"] {
            let sha = source["source"][input]["sha256"].as_str().unwrap();
            assert_eq!(
                sha.len(),
                64,
                "{input} records the SHA-256 of what it was made from"
            );
        }
    }

    #[test]
    fn every_name_means_one_widget_whatever_its_case() {
        let mut seen = BTreeSet::new();
        for widget in &catalog().widgets {
            for name in widget.names() {
                assert!(
                    seen.insert(name.to_ascii_lowercase()),
                    "{name} names two widgets"
                );
            }
        }
    }

    #[test]
    fn a_legacy_type_id_never_resolves_to_a_modern_widget() {
        let catalog = catalog();
        for word in [
            "tree",
            "collection",
            "container",
            "panel",
            "button",
            "label",
            "tabs",
            "navigation",
            "autorefresh",
        ] {
            let error = catalog.resolve(word).unwrap_err();
            assert!(
                matches!(error, CatalogError::Legacy { .. }),
                "{word}: {error}"
            );
            assert!(
                error.to_string().contains("legacy widget"),
                "{word}: {error}"
            );
        }
        // Friendly words that are not type ids keep working.
        for (word, type_id) in [
            ("tree-selector", "ptcstreeselector"),
            ("text-field", "ptcstextfield"),
            ("responsive-container", "flexcontainer"),
            ("table", "ptcsgrid"),
            ("input", "ptcstextfield"),
        ] {
            assert_eq!(catalog.resolve(word).unwrap().type_id, type_id);
        }
    }

    #[test]
    fn a_widget_is_found_by_type_or_alias_and_an_unknown_one_suggests_others() {
        let catalog = catalog();
        assert_eq!(catalog.resolve("ptcsgrid").unwrap().type_id, "ptcsgrid");
        assert_eq!(catalog.resolve("Grid").unwrap().type_id, "ptcsgrid");
        assert_eq!(catalog.resolve(" table ").unwrap().type_id, "ptcsgrid");
        assert_eq!(
            catalog.resolve("responsive-container").unwrap().type_id,
            "flexcontainer"
        );
        let error = catalog.resolve("chart").unwrap_err();
        let CatalogError::Unknown { close, .. } = &error else {
            panic!("{error}");
        };
        assert!(close.iter().any(|c| c == "ptcschartbar"), "{close:?}");
        assert_eq!(error.code(), ErrorCode::InvalidArguments);
        assert!(catalog
            .resolve("gizmo")
            .unwrap_err()
            .to_string()
            .contains("twaco widgets"));
    }

    #[test]
    fn defaults_keep_composers_order() {
        let button = catalog().by_type("ptcsbutton").unwrap();
        let keys: Vec<&str> = button.defaults.keys().map(String::as_str).collect();
        assert_eq!(&keys[..3], ["Area", "ButtonType", "ContextID"]);
        assert_eq!(button.defaults["Label"], Value::from("[[Button]]"));
    }

    #[test]
    fn the_contracts_agents_bind_most_are_as_the_10_2_bundle_declares_them() {
        let catalog = catalog();
        let contract = |widget: &str, property: &str| {
            let found = catalog.by_type(widget).unwrap().property(property).unwrap();
            (found.base_type.clone().unwrap(), found.source, found.target)
        };
        assert_eq!(
            contract("ptcsgrid", "Data"),
            ("INFOTABLE".into(), false, true)
        );
        assert_eq!(
            contract("ptcstextfield", "Text"),
            ("STRING".into(), true, true)
        );
        assert_eq!(
            contract("ptcsdropdown", "SelectedText"),
            ("STRING".into(), true, true)
        );
        assert_eq!(
            contract("ptcsmenubar", "PrimaryNavData"),
            ("INFOTABLE".into(), false, true)
        );
        assert!(catalog.by_type("ptcsgrid").unwrap().auto_resize);
        assert!(!catalog.by_type("ptcsbutton").unwrap().auto_resize);
    }

    #[test]
    fn contracts_say_which_way_a_property_binds() {
        let catalog = catalog();
        let grid = catalog.by_type("ptcsgrid").unwrap();
        let data = grid.property("Data").unwrap();
        assert_eq!(
            (data.base_type.as_deref(), data.target),
            (Some("INFOTABLE"), true)
        );
        let text = catalog
            .by_type("ptcstextfield")
            .unwrap()
            .property("Text")
            .unwrap();
        assert!(text.source && text.target, "{text:?}");
        // Every widget has Visible, though no contract lists it.
        assert!(grid.property("Visible").unwrap().target);
        assert!(catalog.by_type("ptcsbutton").unwrap().has_event("Clicked"));
        let container = catalog.by_type("flexcontainer").unwrap();
        assert!(container.container && container.has_contract());
        assert!(container.property("Visible").unwrap().target);
        assert!(container.property("CustomClass").unwrap().source);
        assert!(!container.property("SourceURL").unwrap().target);
        for service in ["ToggleExpandCollapse", "Expand", "Collapse"] {
            assert!(container
                .services
                .as_ref()
                .unwrap()
                .iter()
                .any(|name| name == service));
        }
        assert_eq!(
            container
                .property("ExpandCollapseTabLocation")
                .unwrap()
                .allowed_values()
                .cloned()
                .collect::<Vec<_>>(),
            vec![Value::from("inside"), Value::from("outside")]
        );
    }
}
